import{_ as e,b as a,a as t,aS as o}from"./chunks/framework.M2Whok06.js";const f=JSON.parse('{"title":"百度网盘","description":"","frontmatter":{},"headers":[],"relativePath":"note/software/win-tool/百度网盘.md","filePath":"note/software/win-tool/百度网盘.md","lastUpdated":1741789194000}'),s={name:"note/software/win-tool/百度网盘.md"},r=o('<h1 id="百度网盘" tabindex="-1">百度网盘 <a class="header-anchor" href="#百度网盘" aria-label="Permalink to &quot;百度网盘&quot;">​</a></h1><h2 id="如何下载历史版本" tabindex="-1">如何下载历史版本 <a class="header-anchor" href="#如何下载历史版本" aria-label="Permalink to &quot;如何下载历史版本&quot;">​</a></h2><p>1、 历史版本查询：</p><p>百度网盘官方提供了历史版本查询的页面：<a href="https://pan.baidu.com/disk/version" target="_blank" rel="noreferrer">https://pan.baidu.com/disk/version</a> 你可以在这里查看各个版本的更新内容，选择一个适合自己的版本。</p><p>2、下载链接：</p><p>Windows 版本（7.30.5.2）： 这是一个比较稳定的老版本，推荐使用。</p><p>下载地址：<a href="https://issuepcdn.baidupcs.com/issue/netdisk/yunguanjia/BaiduNetdisk_7.30.5.2.exe" target="_blank" rel="noreferrer">https://issuepcdn.baidupcs.com/issue/netdisk/yunguanjia/BaiduNetdisk_7.30.5.2.exe</a></p><p>PS：后面的版本号是可以自己替换的！！！</p><h2 id="禁止-百度网盘-自动升级更新" tabindex="-1">禁止 百度网盘 自动升级更新 <a class="header-anchor" href="#禁止-百度网盘-自动升级更新" aria-label="Permalink to &quot;禁止 百度网盘 自动升级更新&quot;">​</a></h2><p>1、找到百度网盘安装目录</p><p>在电脑桌面百度网盘快捷方式上点 “右键”，点 “打开文件所在的位置”。</p><p>2、找到自动升级组件</p><p>找到文件夹 “AutoUpdate”, 把这个文件夹 “删除” 或者 “重命名为任意名称”。</p><p>找到文件 “autoDiagnoseUpdate.exe”, 把这个文件 “删除” 或者 “重命名为任意名称”。</p><p>找到文件 “kernelUpdate.exe”, 把这个文件 “删除” 或者 “重命名为任意名称”。</p>',15),n=[r];function i(p,d,_,c,l,h){return t(),a("div",null,n)}const m=e(s,[["render",i]]);export{f as __pageData,m as default};
